<h2>Calculate qPCR amplification efficiency</h2><p class="lead">Convert standard-curve slope into amplification efficiency, fold amplification per cycle and deviation from ideal doubling.</p><div class="notice">Efficiency acceptance is assay- and SOP-specific. Use the full standard-curve quality assessment, not efficiency alone.</div><div class="form-grid"><div class="field"><label for="slope">Standard-curve slope</label><input id="slope" type="number" value="-3.322" step="any"></div><div class="field"><label for="r2in">Optional R² from standard curve</label><input id="r2in" type="number" value="0.995" min="0" max="1" step="any"></div></div><div class="tool-actions"><button class="btn btn-primary" id="calc" type="button">Calculate</button><button class="btn btn-secondary" id="reset" type="button">Reset</button></div><div class="result-box"><div class="result-grid"><div class="metric"><span>Amplification efficiency</span><strong id="eff">—</strong></div><div class="metric"><span>Fold per cycle</span><strong id="fold">—</strong></div><div class="metric"><span>Deviation from 100%</span><strong id="ideal">—</strong></div><div class="metric"><span>Rule-of-thumb range check</span><strong id="range">—</strong></div></div><div id="note" class="helper" style="margin-top:12px"></div></div><script>
(()=>{
const $=id=>document.getElementById(id); const num=id=>Number($(id).value); const fmt=(v,d=2)=>Number.isFinite(v)?v.toLocaleString(undefined,{maximumFractionDigits:d}):'—';
const defaults={}; document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>defaults[el.id]=el.value);
function clear(){$('eff').textContent='—';$('fold').textContent='—';$('ideal').textContent='—';$('range').textContent='—'; const n=$('note'); if(n){n.textContent='';n.className='helper';}}
function calculate(){try{const s=num('slope'),r=num('r2in');if(!(s<0&&r>=0&&r<=1))throw 0;const E=Math.pow(10,-1/s),pct=(E-1)*100,dev=pct-100;$('eff').textContent=fmt(pct,2)+'%';$('fold').textContent=fmt(E,4)+'×';$('ideal').textContent=(dev>=0?'+':'')+fmt(dev,2)+' points';$('range').textContent=(pct>=90&&pct<=110&&r>=0.98)?'Within common guide':'Review assay / curve';$('note').textContent='Bio-Rad gives efficiency (%) = (10^(−1/slope) − 1) × 100 and commonly cites 90–110% with R² around/above 0.98 as a preferred standard-curve range.';}catch(e){clear(); const n=$('note'); if(n){n.textContent='Please check the inputs and try again.';n.className='helper danger';}}}
const c=$('calc'); if(c)c.addEventListener('click',calculate); const r=$('reset'); if(r)r.addEventListener('click',()=>{Object.entries(defaults).forEach(([id,v])=>{if($(id))$(id).value=v});calculate();});
document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>el.addEventListener('input',calculate));
calculate();
})();
</script>
